```js
const { faceEmbeddings, Delegate, ProgrammeDelegate, ScanEvent, user, sequelize } = require('./models');
const crypto = require('crypto');

async function recognize(req, res) {
    const { id } = req.params;
    const { image } = req.body;

    if (!image) {
        return res.status(400).json({ error: 'image is required' });
    }

    try {
        // Convert base64 to buffer
        const imageBuffer = Buffer.from(image, 'base64');

        // Get face embeddings from captured image (dynamic import because facenetClient is ESM)
        const { getFaceEmbeddings } = await import('../facial_recog/facenetClient.js');
        const capturedFaces = await getFaceEmbeddings(imageBuffer);

        if (capturedFaces.length === 0) {
            return res.json({ matches: [] });
        }

        // Fetch all primary face embeddings from DB
        const storedEmbeddings = await faceEmbeddings.findAll({
            where: { imageType: 'primary' }
        });

        // Compute cosine similarity and find matches
        const matches = [];
        const threshold = 0.5;

        for (const captured of capturedFaces) {
            const capturedEmbedding = captured.embedding;

            for (const stored of storedEmbeddings) {
                const storedEmbedding = JSON.parse(stored.embeddings);
                const similarity = cosineSimilarity(capturedEmbedding, storedEmbedding);

                if (similarity >= threshold) {
                    // Look up delegate by userId
                    const delegate = await Delegate.findOne({
                        where: { userId: stored.userId },
                        include: [{
                            model: ProgrammeDelegate,
                            as: 'programmeDelegates',
                            where: { programmeId: id },
                            required: true
                        }]
                    });

                    if (delegate) {
                        // Log scan event
                        await ScanEvent.create({
                            programmeId: id,
                            delegateId: delegate.id,
                            confidence: similarity,
                            status: 'verified'
                        });

                        matches.push({
                            delegateId: delegate.id,
                            name: delegate.name,
                            confidence: similarity
                        });
                    }
                }
            }
        }

        // Log unverified scan events for unmatched captured faces
        for (const captured of capturedFaces) {
            const matched = matches.some(m => m.delegateId); // not quite right
            // Actually, we don't have a way to track which captured face didn't match anything
            // Let's log a single unverified event if no matches
        }

        if (matches.length === 0) {
            await ScanEvent.create({
                programmeId: id,
                status: 'unverified',
                unverifiedReason: 'No matching face found'
            });
        }

        // Sort by confidence descending
        matches.sort((a, b) => b.confidence - a.confidence);

        // Deduplicate by delegateId (keep highest confidence)
        const seen = new Set();
        const uniqueMatches = [];
        for (const m of matches) {
            if (!seen.has(m.delegateId)) {
                seen.add(m.delegateId);
                uniqueMatches.push(m);
            }
        }

        res.json({ matches: uniqueMatches });
    } catch (err) {
        console.error('[Recognize] Error:', err);
        res.status(500).json({ error: err.message });
    }
}

function cosineSimilarity(a, b) {
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;
    for (let i = 0; i < a.length; i++) {
        dotProduct += a[i] * b[i];
        normA += a[i] * a[i];
        normB += b[i] * b[i];
    }
    const denom = Math.sqrt(normA) * Math.sqrt(normB);
    if (denom === 0) return 0;
    return dotProduct / denom;
}

module.exports = { recognize };
