const { sequelize } = require('./database/db.cjs');
const tables = [
    'offline_queue', 'chat_messages', 'scan_events', 'programme_delegates',
    'ready_to_depart', 'attendance_records', 'staff', 'delegates',
    'routes', 'programmes', 'faceEmbeddings', 'admins', 'attendees',
    'messages', 'users'
];
sequelize.query(`DROP TABLE IF EXISTS ${tables.map(t => `"${t}"`).join(', ')} CASCADE;`)
    .then(() => { console.log('Tables dropped'); process.exit(0); })
    .catch(e => { console.error(e.message); process.exit(1); });

